def transform_fixed(grid):
    # Properly create 6-column output
    h, w = len(grid), len(grid[0])

    # Start with frame, then modify interior
    output = [[0]*6 for _ in range(h)]
    for r in range(h):
        for c in range(6):
            output[r][c] = grid[r][c]  # Copy frame

    # Find shape colors by band (use min row)
    color_min_row = {}  # color -> minimum row containing this color
    for r in range(h):
        for c in range(8, w - 2):
