    color_list = sorted(color_min_row.keys(), key=lambda c: color_min_row[c])

    if len(color_list) <= 1:
        return output

    # Color shift: each color → next color in sorted order
    n = len(color_list)
    shift = {color_list[i]: color_list[(i+1) % n] for i in range(n)}

    # Determine which rows get filled and with which color
    for r in range(h):
        # Find interior tuple
        interior = tuple(grid[r][1:5])

        # Find this row's color
        row_color = None
        for c in range(8, w-2):
